-- Carga inicial de los 3 tests del documento "CUIDAPP test psicológico para cada área" (12 preguntas c/u).
-- Vinculación: Limpieza del hogar (1) · Niñera / Cuidadora (2) · Adultos mayores (3) + Acompañamiento hospitalario (4).
-- Importantes = los "dilemas" del documento. Red flags = opciones de maltrato, abandono, negligencia médica,
-- hurto, encubrimiento o violación grave de la privacidad (revisarlas en el panel).
-- Umbrales del documento: aprueba 83.3 %, revisión 66.6 %, bloqueo 90 días, 12 minutos.
-- Si un test con el mismo nombre ya existe, no se toca. Ejecutar con sqlcmd -f 65001.
SET NOCOUNT ON;

IF NOT EXISTS (SELECT 1 FROM TestsPsicologicos WHERE Nombre = N'Test de servicios domésticos y limpieza')
    EXEC sp_AdminGuardarTest @Id = NULL, @Nombre = N'Test de servicios domésticos y limpieza', @Descripcion = N'Lee cada situación con calma y elige lo que harías de verdad. No hay respuestas con trampa.',
        @MinutosLimite = 12, @PorcentajeAprobacion = 83.3, @PorcentajeRevision = 66.6, @DiasBloqueo = 90, @Activo = 1,
        @Tipos = '[1]', @Ahora = '2026-10-19',
        @Preguntas = N'[{"texto": "Durante el servicio de limpieza profunda en la sala, un adorno fino de porcelana se cae y se quiebra al mover un estante. Los clientes no están en casa. ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Recoge los fragmentos, los oculta en la bolsa de basura y continúa la limpieza sin mencionar el incidente.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Toma fotografías de los fragmentos y del lugar, limpia el área de forma segura para evitar cortes, e informa de inmediato al empleador y al soporte de Cuidapp con total transparencia.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Intenta pegar las piezas con pegamento instantáneo antes de que regresen los dueños de casa para disimular la rotura.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Deja las piezas rotas sobre la mesa sin comunicar nada y espera a que el empleador le pregunte al regresar.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "El cliente la aborda molesto acusándola de haber tomado un dinero en efectivo que dejó sobre la mesa de noche antes del servicio. Usted no ha tomado nada. ¿Cómo reacciona?", "esCritica": false, "opciones": [{"texto": "Responde de manera agresiva defendiendo su honor, exige una disculpa inmediata y abandona la casa abruptamente.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Conserva la calma y el respeto, ofrece revisar las áreas donde estuvo trabajando para buscar el objeto extraviado y solicita la intermediación formal del soporte de Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Permite que el cliente revise agresivamente sus pertenencias personales o bolso sin estar presente un representante legal o soporte.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Ofrece pagar de su propio dinero el monto faltante para evitar conflictos o ser dada de baja en la aplicación.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Al llegar a prestar un servicio de limpieza, un perro de gran tamaño suelto en el patio muestra comportamientos agresivos (gruñidos y ladridos) impidiendo el acceso seguro a las áreas asignadas. ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Intenta acorralar o asustar al perro con un escobillón o elemento de limpieza para obligarlo a entrar a un cuarto.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene una distancia segura sin confrontar al animal, contacta inmediatamente al dueño para que asegure a la mascota y reporta la contingencia a la aplicación.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Arriesga su integridad física y entra a la zona a trabajar ignorando la actitud agresiva de la mascota.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Cancela el servicio y se retira del lugar inmediatamente sin intentar comunicarse previamente con el cliente.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Durante el servicio de ordenamiento y limpieza en un estudio privado, encuentra documentos financieros confidenciales e identificación esparcida en el escritorio. ¿Cuál es la conducta adecuada?", "esCritica": false, "opciones": [{"texto": "Toma fotografías de los documentos para guardarlas en su teléfono móvil personal como comprobante del estado en que los encontró.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Limpia alrededor sin alterar ni leer la documentación sensible, respetando al máximo la privacidad del hogar y notificando discretamente al empleador.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Guarda los documentos dentro de carpetas privadas o cajones bajo llave sin pedir autorización previa.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Comenta el contenido de los documentos financieros con terceras personas por mensajes de texto.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Contratada exclusivamente para limpieza de interiores, el cliente le exige de forma imprevista realizar tareas de riesgo físico en exteriores (lavado de cristales en altura en un segundo piso sin arnés ni protección). ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Realiza la tarea peligrosa para evitar una mala calificación en la app, arriesgando su integridad física.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Explica con amabilidad que dicha labor excede el alcance contratado y representa un riesgo de accidente laboral, ofreciendo centrarse en las áreas seguras y reportando el ajuste a Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Se niega con groserías y se sienta a descansar el resto del turno sin dar explicaciones.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Acepta hacer la tarea bajo condición de recibir un pago extra en efectivo por fuera de la plataforma.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Al limpiar debajo de un mueble, encuentra un sobre con una suma importante de dinero en efectivo y joyas que al parecer llevan meses olvidados. La familia contratante no ha notado su presencia. ¿Qué hace?", "esCritica": true, "opciones": [{"texto": "Los guarda discretamente en su bolso pensando que nadie los reclamará al haber pasado tanto tiempo.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Se los lleva a su casa para resguardarlos y espera a que los dueños le pregunten por ellos en el futuro.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Los deja exactamente en el mismo lugar donde estaban, toma una fotografía como constancia de su ubicación y avisa inmediatamente al empleador y al soporte de Cuidapp para su resguardo formal.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Los deja sobre la mesa principal a la vista de cualquier persona que visite la casa.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Se presenta un embotellamiento severo en el transporte público de Santo Domingo que retrasará su llegada al servicio de limpieza por 35 minutos. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Viaja en silencio y le avisa al cliente únicamente al tocar la puerta de la vivienda.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Notifica inmediatamente la contingencia al cliente y a la plataforma Cuidapp mediante la app, compartiendo su estatus y un estimado real de llegada.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Cancela el servicio por cuenta propia asumiendo que el cliente contratará a otra persona.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Apaga el teléfono móvil para evitar llamadas de reclamo mientras llega al sector.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "El cliente le pide mezclar dos productos de limpieza distintos (cloro y amoníaco/ácido) para acelerar el blanqueo de los pisos del baño. Usted sabe por inducción que esto genera vapores tóxicos peligrosos. ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Realiza la mezcla tal cual lo solicita el cliente para no contrariarlo ni generar discusiones.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Explica con respeto el riesgo químico para la salud que representa esa mezcla, sugiriendo usar los productos de forma segura por separado según los protocolos de Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Mezcla los productos a escondidas en un envase pequeño para cumplir rápido sin que lo note.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Arroja los productos al excusado y se niega a realizar la limpieza del baño.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Durante la jornada de limpieza, el cliente le pide de favor que salga a un colmado cercano a comprarle bebidas alcohólicas y cigarrillos con su propio dinero, prometiendo reembolsárselo luego. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Sale corriendo a hacer el mandado de inmediato para ganarse una propina adicional.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Explica amablemente que por políticas de seguridad y cobertura de la plataforma su labor se circunscribe exclusivamente al mantenimiento del hogar acordado.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le grita al cliente indicándole que ella no es mandadera y se encierra en una habitación.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Le presta su dinero y hace el mandado por fuera del registro de la aplicación.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Al limpiar el área de la televisión y consolas de videojuegos, se percata de que un cable principal está flojo y el aparato se apaga bruscamente. Al encenderlo de nuevo, presenta un fallo en la pantalla. ¿Qué hace?", "esCritica": false, "opciones": [{"texto": "Desconecta todo y esconde el equipo dañado dentro de un mueble para que no la acusen.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Detiene la manipulación del aparato, toma nota del estado en que quedó y avisa de inmediato al empleador y a soporte para revisar lo ocurrido con honestidad.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Intenta desarmar la pantalla con un destornillador para arreglar el circuito interno por su cuenta.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Se marcha del hogar sin decir nada antes de que el cliente regrese.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Durante un servicio de limpieza a solas en la residencia, se presenta un desconocido en la puerta asegurando ser un técnico de reparaciones urgente enviado por el administrador del edificio, exigiendo ingresar a revisar tuberías con una actitud sospechosa. Los dueños no contestan el teléfono. ¿Cómo resuelve esta situación crítica?", "esCritica": true, "opciones": [{"texto": "Le abre la puerta de inmediato para evitar problemas con la administración del condominio.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene la puerta cerrada con pestillo de seguridad, le indica que no hay autorización previa de los dueños, se comunica con la seguridad del edificio y activa una alerta en Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le permite pasar a la cocina mientras ella sigue limpiando la sala sin prestar atención.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Sale de la casa dejando la puerta abierta para que el supuesto técnico entre y resuelva rápido.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al ordenar una gaveta en la habitación principal durante la limpieza rutinaria, encuentra por accidente paquetes sospechosos con sustancias controladas (drogas ilícitas) o armas de fuego sin registro visibles. ¿Cuál es la conducta correcta bajo los estándares legales y de la plataforma?", "esCritica": true, "opciones": [{"texto": "Tomar fotografías con su celular personal para extorsionar o chantajear al cliente en el futuro.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Guardar los objetos en su bolso personal para llevárselos y deshacerse de ellos en la calle.", "esCorrecta": false, "esRedFlag": true}, {"texto": "No tocar absolutamente nada bajo ningún concepto, retirarse de inmediato de esa zona específica y notificar de manera confidencial al canal de cumplimiento y soporte de Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Llamar a vecinos y amigos por teléfono para contarles el gran secreto que descubrió en la casa.", "esCorrecta": false, "esRedFlag": true}]}]';
GO

IF NOT EXISTS (SELECT 1 FROM TestsPsicologicos WHERE Nombre = N'Test para niñeras (cuidado infantil)')
    EXEC sp_AdminGuardarTest @Id = NULL, @Nombre = N'Test para niñeras (cuidado infantil)', @Descripcion = N'Lee cada situación con calma y elige lo que harías de verdad. No hay respuestas con trampa.',
        @MinutosLimite = 12, @PorcentajeAprobacion = 83.3, @PorcentajeRevision = 66.6, @DiasBloqueo = 90, @Activo = 1,
        @Tipos = '[2]', @Ahora = '2026-10-19',
        @Preguntas = N'[{"texto": "Durante el almuerzo, un niño de 5 años consume por accidente un alimento con trozos de maní y comienza a presentar dificultad respiratoria e inflamación en el rostro. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Le da un vaso de agua, lo recuesta en el sofá para que descanse y espera 20 minutos a ver si los síntomas disminuyen antes de avisar.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Mantiene la calma, activa inmediatamente los servicios de emergencia médica (911/emergencias), aplica el protocolo de alergias/autoinyector si está autorizado e informa de inmediato a los padres.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Llama primero a los padres para pedirles instrucciones detalladas y espera su llegada a la vivienda sin contactar emergencias.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Le administra un antihistamínico de venta libre que encuentra en el botiquín del hogar sin previa indicación ni prescripción médica.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Un niño de 4 años bajo su cuidado se niega rotundamente a comer sus verduras y comienza a llorar y a lanzar los juguetes al suelo. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Le quita los juguetes de inmediato, lo envía a su habitación a reflexionar y no le da de comer hasta que se calme por completo.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene la calma, valida la emoción del niño reconociendo su molestia, recoge los juguetes de forma segura y le propone una dinámica lúdica para probar la comida.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le ofrece un dulce o un premio azucarado a cambio de que deje de llorar y termine sus alimentos rápidamente.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Llama de inmediato a los padres por teléfono para que ellos le llamen la atención al niño de forma remota.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Mientras realiza sus labores con los niños a cargo, suena el timbre y se presenta una persona afirmando ser familiar del dueño de casa exigiendo entrar. Los clientes no le avisaron nada. ¿Qué hace?", "esCritica": false, "opciones": [{"texto": "Le permite la entrada de inmediato al ver que la persona viste bien y habla con mucha seguridad y familiaridad.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene la puerta cerrada con seguro, le pide amablemente que espere afuera y se comunica directamente con el titular del servicio para verificar y autorizar el acceso.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le permite esperar adentro en el recibidor mientras intenta llamar por teléfono a sus contratantes.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Abandona la propiedad junto con los niños para no tener que tratar con la persona en la puerta.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Mientras usted prepara un tetero en la cocina, deja al bebé de 1 año jugando en la alfombra de la sala. De repente escucha un silencio sospechoso y ruidos de objetos pequeños cerca de su boca. ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Termina de calentar el tetero con calma y luego va a ver qué hace el niño para no interrumpir su labor en la cocina.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Deja inmediatamente lo que está haciendo en la cocina, acude de inmediato a la sala a revisar al menor, retira cualquier objeto riesgoso de su alcance y asegura el espacio.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Llama a gritos al niño desde la cocina para que le devuelva lo que tiene en la mano.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Espera a que el niño llore para confirmar si tragó algo peligroso.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Contratada exclusivamente para el cuidado de un infante, el cliente le exige durante el turno realizar tareas pesadas de limpieza exterior con químicos fuertes (lavado de fachada) descuidando al menor. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Realiza las tareas peligrosas dejando al niño solo por momentos para cumplir con los dueños.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Explica con amabilidad que su enfoque exclusivo es la seguridad y cuidado del menor, y que realizar ambas tareas simultáneamente pone en riesgo la integridad del niño, notificando el caso a Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Deja al niño viendo televisión sin supervisión durante horas para dedicarse por completo a limpiar la fachada.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Se niega con insultos y abandona el servicio llevándose al niño a la calle.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Durante un turno a solas con los niños en la residencia, se percata de que un intruso forzó la cerradura trasera e ingresó a la planta baja de la vivienda. Los padres están en tránsito y sin señal. ¿Cuál es su protocolo de acción inmediato?", "esCritica": true, "opciones": [{"texto": "Sale corriendo con los niños a la calle pidiendo ayuda a gritos sin verificar rutas seguras.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Baja a confrontar al intruso con un objeto pesado para defender la propiedad y a los menores.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Encierra rápidamente a los niños y a usted en una habitación segura con pestillo, bloquea la entrada, activa de forma discreta la alerta SOS en la app de Cuidapp y llama en silencio a la policía.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Deja a los niños en la sala y se esconde sola en el baño esperando a que pase la situación.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Un infante de 2 años bajo su cuidado comienza a elevar la temperatura corporal de forma abrupta y presenta episodios de rigidez muscular leve (convulsión febril). ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Lo sumerge de inmediato en agua completamente helada para bajarle la temperatura a la fuerza.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene la calma, coloca al niño de costado en posición de seguridad para evitar asfixia, retira objetos cercanos, llama inmediatamente a emergencias (911) y avisa a los padres.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le administra una sobredosis de medicamentos antipiréticos de adultos que encuentra en el botiquín.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Lo envuelve en varias cobijas gruesas para que sude la fiebre y espera a que pase el turno.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Para mantener a los niños tranquilos durante todo el día, los padres le han pedido moderar el uso de tabletas, pero a usted le resulta más cómodo dejarlos frente a la pantalla por horas para evitar que jueguen o ensucien. ¿Qué decide hacer?", "esCritica": false, "opciones": [{"texto": "Deja la tableta encendida todo el día ignorando las pautas de crianza de los padres para descansar.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Respeta estrictamente los tiempos pautados de pantallas, propiciando actividades didácticas, lectura o juegos creativos adecuados a su edad.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Oculta los dispositivos y deja a los niños sin ningún tipo de entretenimiento ni supervisión.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Les permite jugar videojuegos violentos no aptos para su edad con tal de que obedezcan.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Tiene la responsabilidad de buscar al niño al colegio a una hora exacta, pero el transporte escolar o público sufre un retraso masivo. ¿Cómo gestiona la situación?", "esCritica": false, "opciones": [{"texto": "Se desentiende y espera que el colegio resuelva solo la situación del menor.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Notifica de inmediato al colegio informando la demora, avisa a los padres y actualiza el estatus en tiempo real mediante el soporte de la aplicación Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Apaga el teléfono móvil para evitar llamadas de reclamo de la familia.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Camina por vías inseguras arriesgando su integridad para llegar a cualquier costo.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Mientras limpia brevemente el baño, deja un envase abierto con desinfectante clorado en el suelo al alcance de un niño gateando que se dirige directo hacia él. ¿Cuál es su reacción?", "esCritica": false, "opciones": [{"texto": "Espera a terminar de limpiar el área del lavamanos antes de prestar atención al menor.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Detiene de inmediato la tarea, aparta el producto químico a una zona alta bajo llave y reubica al infante en un espacio totalmente seguro.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le grita al niño desde lejos para que se aleje por sí solo del envase.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Ignora el riesgo asumiendo que el niño solo lo olerá sin mayores consecuencias.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Mientras se encontraba distraída respondiendo un mensaje personal en su teléfono, un niño de 3 años trepa por las barandas del balcón o escalera y sufre una caída desde una altura considerable, quedando inconsciente y con respiración irregular. Los padres están ilocalizables. ¿Cómo resuelve esta crisis extrema?", "esCritica": true, "opciones": [{"texto": "Intenta ocultar lo sucedido acomodando al niño en su cama y esperando a que despierte solo para evitar ser despedida.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Asume la responsabilidad de inmediato, evalúa signos vitales, activa la alerta SOS y los servicios de emergencia (911) sin dilación, y guía la atención clínica informando con absoluta transparencia a los padres y a Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Sale corriendo a la calle a esconderse por temor a enfrentar cargos legales o culpas familiares.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Llama únicamente a una vecina para pedirle consejo y demora la llamada a emergencias médicas.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al cambiar de ropa a un niño menor de edad, usted nota marcas físicas evidentes de maltrato o violencia reiterada que provienen del entorno intrafamiliar habitual. Al consultarlo discretamente con un familiar directo que convive allí, este le amenaza con destruirla profesionalmente si abre la boca. ¿Cuál es el procedimiento ético correcto?", "esCritica": true, "opciones": [{"texto": "Callar y obedecer la advertencia del familiar para conservar el empleo en ese hogar.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Renunciar en silencio y abandonar al menor a su suerte sin reportar nada a las autoridades.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Utilizar de inmediato el canal seguro de cumplimiento, auditoría y soporte de Cuidapp para reportar la evidencia de riesgo infantil, permitiendo la activación de los protocolos legales de protección al menor.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Grabar un video de los niños y publicarlo masivamente en redes sociales para denunciar el caso por cuenta propia.", "esCorrecta": false, "esRedFlag": true}]}]';
GO

IF NOT EXISTS (SELECT 1 FROM TestsPsicologicos WHERE Nombre = N'Test para adultos mayores y acompañamiento hospitalario')
    EXEC sp_AdminGuardarTest @Id = NULL, @Nombre = N'Test para adultos mayores y acompañamiento hospitalario', @Descripcion = N'Lee cada situación con calma y elige lo que harías de verdad. No hay respuestas con trampa.',
        @MinutosLimite = 12, @PorcentajeAprobacion = 83.3, @PorcentajeRevision = 66.6, @DiasBloqueo = 90, @Activo = 1,
        @Tipos = '[3,4]', @Ahora = '2026-10-19',
        @Preguntas = N'[{"texto": "Un adulto mayor bajo su cuidado pierde el equilibrio en el baño, cae al suelo y expresa sentir un fuerte dolor en la cadera, siendo incapaz de levantarse. ¿Cuál es su reacción?", "esCritica": false, "opciones": [{"texto": "Intenta levantarlo con fuerza para sentarlo en una silla cercana y comprobar si puede caminar.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Evita moverlo para no agravar una posible fractura, evalúa su estado de conciencia, brinda contención emocional, llama a emergencias y notifica inmediatamente a la familia.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le aplica masajes y pomadas antiinflamatorias en la zona afectada para calmar el dolor y espera a la noche.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Le pide al paciente que haga un esfuerzo por ponerse de pie solo para descartar que sea un golpe menor.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Un adulto mayor con deterioro cognitivo leve insiste en salir solo a la calle a \"ir a trabajar\", manifestando desorientación temporal y alteración emocional. ¿Cuál es su reacción?", "esCritica": false, "opciones": [{"texto": "Le explica de forma firme y directa que ya no trabaja, mostrándole un calendario para convencerlo de su realidad por la fuerza.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Escucha con empatía, valida sus sentimientos, le conversa sobre sus años laborales y desvía pacientemente su atención hacia una actividad segura dentro del hogar.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le cierra la puerta con llave de inmediato y le ordena sentarse de forma agresiva a ver televisión para evitar que hable.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Lo deja salir a la puerta a ver si se le pasa la ocurrencia por sí sola.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Se interrumpe el suministro eléctrico en la vivienda mientras la persona bajo su cuidado (con movilidad reducida) necesita usar un equipo de asistencia respiratoria y recibir una medicina programada. ¿Qué hace?", "esCritica": false, "opciones": [{"texto": "Espera en penumbra a que regrese la energía eléctrica por sí sola, postergando la atención médica indefinidamente.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Conserva la calma, activa la planta/inversor de emergencia o fuentes de luz seguras (linternas), verifica las instrucciones clínicas y avisa al contacto de emergencia manteniendo al paciente tranquilo.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Llama al 911 exigiendo que la compañía eléctrica restablezca la luz de inmediato en la cuadra.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Enciende múltiples velas alrededor de la cama del paciente clínico desatendiendo el riesgo de gases o fuego.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Al finalizar su jornada habitual de 8 horas cuidando a un paciente convaleciente post-quirúrgico, el empleador le exige quedarse 5 horas más de forma imprevista. Usted se siente extenuada y esto compromete su alerta médica nocturna. ¿Cómo reacciona?", "esCritica": false, "opciones": [{"texto": "Acepta quedarse callada por temor a una mala calificación en la app, arriesgándose a cometer errores en la administración de medicamentos por cansancio.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Explica con asertividad y respeto su nivel de fatiga física y el riesgo clínico que implica para el paciente, ofreciendo coordinar un relevo seguro a través de la plataforma Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Entra en discusión acalorada insultando al empleador y abandona al paciente inmediatamente sin supervisión.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Acepta el tiempo extra y duerme profundamente junto al paciente desatendiendo las alarmas de los monitores.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al momento de suministrar un medicamento intravenoso u oral recetado en horario estricto a un paciente encamado, nota que la etiqueta del frasco tiene una borradura parcial en la dosis exacta. ¿Cómo procede?", "esCritica": false, "opciones": [{"texto": "Administra una cantidad estimada a su propio criterio para no retrasar la hora del tratamiento.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Detiene la administración de inmediato, consulta la receta médica original y se comunica con el médico tratante o familiar responsable antes de suministrar cualquier dosis.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Omite por completo la toma de ese horario y espera al día siguiente para ver si alguien lo nota.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Le pide al propio paciente que decida cuántas pastillas debe tomarse según cómo se sienta.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Durante el aseo de un paciente adulto mayor con movilidad nula, observa un enrojecimiento persistente e inicio de lesión cutánea en la zona lumbar. ¿Qué acción debe tomar?", "esCritica": false, "opciones": [{"texto": "Aplica alcohol directamente y frota con fuerza la zona afectada para reactivar la circulación.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Evita la presión continua sobre el área, realiza los cambios posturales pautados en el protocolo clínico, aplica cremas barreras indicadas y reporta el hallazgo en el reporte diario y a la familia.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Coloca vendas apretadas para tapar la piel roja y oculta la situación a los familiares.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Deja al paciente acostado en la misma posición durante todo el día siguiente.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al tomar los signos vitales rutinarios a un paciente hipertenso, registra una presión arterial extremadamente alta acompañada de mareo severo y dolor de cabeza intenso. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Le da un café bien cargado y le pide que se acueste a dormir un rato esperando que baje sola.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene al paciente en reposo absoluto semisentado, notifica de inmediato a los servicios de emergencia médica (911) y avisa a los familiares siguiendo el protocolo clínico de Cuidapp.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le administra pastillas sobrantes de otro familiar que tengan efecto relajante sin prescripción.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Lo anima a caminar por la habitación para que oxigene el cerebro y se le pase el mareo.", "esCorrecta": false, "esRedFlag": false}]}, {"texto": "Durante el turno con un paciente gastrectomizado, nota que la sonda de alimentación presenta una obstrucción y el paciente manifiesta molestias. ¿Cuál es su reacción técnica?", "esCritica": false, "opciones": [{"texto": "Fuerza la jeringa con líquido a presión alta para despejar el conducto a la fuerza.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Suspende la administración de alimentos, verifica si hay dobleces en la manguera y notifica al servicio médico o supervisor siguiendo los pasos de bioseguridad establecidos.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Corta un pedazo de la sonda con tijeras comunes para eliminar la parte obstruida por su cuenta.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Retira la sonda por completo tirando de ella con fuerza sin tener entrenamiento clínico.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Un paciente adulto mayor en recuperación post-operatoria despierta en la madrugada desorientado, intentando arrancarse las vías intravenosas y levantarse bruscamente de la cama. ¿Cómo actúa?", "esCritica": false, "opciones": [{"texto": "Lo ata de manos y pies con sábanas a la estructura de la cama de forma violenta para inmovilizarlo.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Se acerca con voz calmada, le reorienta suavemente en tiempo y espacio, evita que se lastime y solicita apoyo médico o del familiar de guardia manteniendo la contención segura.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Le grita con enojo para obligarlo a acostarse y apaga la luz para que se duerma obligado.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Lo deja solo en la habitación para evitar que la agreda verbalmente.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al cuidar a un paciente bajo un programa de cuidados paliativos, nota que los familiares se muestran distantes y abrumados, delegando toda la carga emocional y física exclusivamente en usted sin relevo. ¿Cómo maneja la situación?", "esCritica": false, "opciones": [{"texto": "Juzga y recrimina duramente a la familia tratándolos de irresponsables y egoístas.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Mantiene la empatía profesional, brinda un trato digno y humano al paciente hasta el último momento, y canaliza a través de Cuidapp la necesidad de mediación y soporte de relevo con los familiares.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Abandona el puesto de trabajo de manera súbita sin importarle el estado del paciente.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Aisla por completo al paciente impidiendo cualquier visita de sus seres queridos.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Durante su turno de cuidado nocturno, un familiar directo del cliente (que no reside en la vivienda, pero posee llaves) ingresa en estado de evidente ebriedad, exigiendo de forma agresiva las llaves de la caja fuerte y dinero en efectivo. La persona cuidada duerme. ¿Cómo resuelve esta crisis?", "esCritica": true, "opciones": [{"texto": "Le entrega las llaves de inmediato para evitar que agreda a la trabajadora o despierte al paciente.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Se enfrenta físicamente a la persona en la entrada para bloquearle el paso a la habitación.", "esCorrecta": false, "esRedFlag": false}, {"texto": "Abre la aplicación de Cuidapp, activa discretamente el protocolo de alerta SOS, se resguarda en una habitación segura junto con el paciente vulnerable y bloquea la puerta mientras notifica a las autoridades.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Sale corriendo de la casa dejando al adulto mayor solo, pidiendo auxilio en la calle.", "esCorrecta": false, "esRedFlag": true}]}, {"texto": "Al realizar el aseo de un adulto mayor dependiente, descubre indicios claros de desatención crónica por parte de un familiar con el que convive (medicamentos vencidos ocultos y signos de deshidratación severa). El familiar le prohíbe reportarlo bajo amenazas de difamarla. ¿Cuál es la conducta correcta?", "esCritica": true, "opciones": [{"texto": "Guardar silencio y acatar la advertencia del familiar para conservar el puesto de trabajo y evitar problemas.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Renunciar de inmediato y marcharse sin decir nada a nadie para no involucrarse.", "esCorrecta": false, "esRedFlag": true}, {"texto": "Denunciar el hecho de forma confidencial e inmediata a través del canal de auditoría y soporte de Cuidapp, aportando evidencias para proteger la vida del paciente y activar los protocolos legales.", "esCorrecta": true, "esRedFlag": false}, {"texto": "Discutir fuertemente con el familiar frente al paciente y amenazarlo con publicar un video en redes sociales.", "esCorrecta": false, "esRedFlag": false}]}]';
GO

SELECT t.Nombre, (SELECT COUNT(*) FROM TestPreguntas p WHERE p.TestId = t.Id) AS Preguntas,
       (SELECT COUNT(*) FROM TestPreguntas p WHERE p.TestId = t.Id AND p.EsCritica = 1) AS Importantes,
       (SELECT COUNT(*) FROM TestOpciones o JOIN TestPreguntas p ON p.Id = o.PreguntaId WHERE p.TestId = t.Id AND o.EsRedFlag = 1) AS RedFlags,
       (SELECT STRING_AGG(tp.Nombre, ', ') FROM TestsPsicologicosTipos x JOIN TiposTrabajos tp ON tp.Id = x.TipoTrabajoId WHERE x.TestId = t.Id) AS Servicios
FROM TestsPsicologicos t ORDER BY t.Id;
